<template>
  <view class="page">
    <view class="hero">
      <view>
        <text class="eyebrow">财务管理</text>
        <text class="hero-title">库存查询</text>
      </view>
    </view>
    <view class="work-scope"><view class="work-scope-mark"></view><view class="work-scope-copy"><text class="work-scope-label">当前部门 · </text><text class="work-scope-name">{{ currentDeptName || '当前部门' }}</text></view></view>
    <view class="summary-bar" v-if="report"><view><text class="summary-value">¥{{ money(report.closingAmount) }}</text><text class="summary-label">库存金额</text></view><view><text class="summary-value">{{ report.closingQuantity || 0 }}</text><text class="summary-label">库存数量</text></view><view><text class="summary-value">{{ items.length }}</text><text class="summary-label">商品数</text></view></view>
    <scroll-view scroll-y class="scroll" refresher-enabled :refresher-triggered="refreshing" @refresherrefresh="refresh">
      <view v-if="stateStatus === 'normal'" class="section-card inventory-list">
        <view class="inventory-card" v-for="item in items" :key="`${item.deptId}-${item.productId}`" @tap="openLedger(item)">
          <view class="inventory-card-head"><view><text class="product-name">{{ item.productName || '-' }}</text><text class="dept-text">{{ item.deptName || item.deptId || '-' }}</text></view><text class="stock-entry">流水 ›</text></view>
          <view class="inventory-card-main"><view><text>库存数量</text><strong>{{ item.closingQuantity || 0 }}</strong></view><view><text>平均成本</text><strong>¥{{ money(item.avgUnitCost, 6) }}</strong></view><view class="amount-cell"><text>库存金额</text><strong>¥{{ money(item.closingAmount) }}</strong></view></view>
        </view>
      </view>
      <view v-else class="section-card state-card"><StateView :status="stateStatus" :message="loadError" @retry="load" /></view>
    </scroll-view>
  </view>
</template>

<script>
import { getStockValueReport } from '@/api/stock.js'
import { requireModulePermission } from '@/utils/permission.js'
import { workContext } from '@/utils/workContext.js'
import StateView from '@/components/StateView.vue'
import { getStatusBarHeight } from '@/utils/systemInfo.js'

export default {
  components: { StateView },
  data() { return { report: null, items: [], loading: false, refreshing: false, loadError: '', currentDeptName: '', statusBarH: 0, menuButton: null } },
  computed: { stateStatus() { if (this.loading && !this.items.length) return 'loading'; if (this.loadError && !this.items.length) return 'error'; if (!this.items.length) return 'empty'; return 'normal' }, headerContentStyle() { const top = this.menuButton?.bottom ? this.menuButton.bottom + 8 : this.statusBarH + 48; return { paddingTop: top + 'px' } } },
  onLoad() { this.statusBarH = getStatusBarHeight(); try { this.menuButton = uni.getMenuButtonBoundingClientRect() } catch (_) { this.menuButton = null }; this.currentDeptName = workContext.snapshot().currentDept?.name || ''; if (requireModulePermission('stockCost')) this.load() },
  methods: {
    money(value, digits = 2) { return Number(value || 0).toFixed(digits) },
    load() {
      this.loading = true
      this.loadError = ''
      getStockValueReport({ startDate: '', endDate: '', pageNum: 1, pageSize: 200 })
        .then(res => { const data = res.data || {}; this.report = data; const scope = workContext.snapshot(); this.currentDeptName = scope.currentDept?.name || ''; this.items = (data.items || []).filter(item => String(item.deptId) === String(scope.currentDeptId)) })
        .catch(e => { this.loadError = e.msg || '库存加载失败'; uni.showToast({ title: this.loadError, icon: 'none' }) })
        .finally(() => { this.loading = false; this.refreshing = false })
    },
    refresh() { this.refreshing = true; this.load() }
    ,openLedger(item) { uni.navigateTo({ url: `/pages/stock-ledger/index?productId=${item.productId}&productName=${encodeURIComponent(item.productName || '')}&deptId=${item.deptId}` }) }
  }
}
</script>

